using System;
using System.Collections;
using System.Linq;
using ExitGames.Client.Photon;
using LogicLegends.OpenArchive.Hunting;
using Photon.Pun;
using Photon.Realtime;
using UnityEngine;

namespace LogicLegends.OpenArchive.Topics.Editor
{
    /// <summary>T5 scenarios use the existing private-room transport and authority harness.</summary>
    public static partial class ArchiveTopicNetworkChecks
    {
        static IEnumerator MethodChoice(Peer peer,int method){yield return Move(peer,session.stations[4],ArchiveMethodPresentation.MethodPosition(method));yield return Send(peer,4,ArchiveAction.Select,method);}
        static IEnumerator TabletPlace(Peer peer,int item,int slot){var st=session.stations[4];var q=session.Question(4);yield return Move(peer,st,st.CurrentItemPosition(item,q,session.State.stations[4]));yield return Send(peer,4,ArchiveAction.Pick,item);yield return Move(peer,st,st.SlotPosition(slot,q));yield return Send(peer,4,ArchiveAction.Place,slot);}
        static IEnumerator TabletArrange(Peer peer,int[] answer){for(int i=0;i<answer.Length;i++)if(session.State.stations[4].placements[i]!=answer[i])yield return TabletPlace(peer,answer[i],i);}
        static IEnumerator MethodsFlow(Peer a,string room){
            var st=session.stations[4];Status="T5 method ownership and attribution";yield return Move(a,st,ArchiveTopicStation.BookPosition+Vector3.back*1.7f);yield return Send(a,4,ArchiveAction.Start);var state=session.State.stations[4];double deadline=state.timerDeadline;
            Check(session.ActiveTopic==4&&state.timerRunning&&state.timerLimit==session.proofMethodsTimeLimitSeconds*session.PacingMultiplier&&state.timerActor==a.Actor,"Guest Book starts the authenticated shared six-minute Proof Forge clock");var q=session.Question(4);
            yield return Move(a,st,new Vector3(0,0,-5));int revision=session.State.revision;Packet(a,Command(a,4,ArchiveAction.Select,q.method));yield return .25f;Check(session.State.revision==revision&&state.selection==-1,"Remote method selection requires proximity to its physical altar");yield return MethodChoice(a,(q.method+1)%3);
            var b=Connect("Archive guest B QA");yield return Wait(()=>b.client.State==ClientState.ConnectedToMasterServer,"T5 guest B connected");b.client.OpJoinRoom(new EnterRoomParams{RoomName=room});yield return Wait(()=>b.client.InRoom&&b.state!=null&&b.state.stations[4].selection==state.selection,"T5 late guest checkpoint");Spawn(b,Position(st,Vector3.zero));yield return Wait(()=>session.ActorPlayer(b.Actor)!=null,"T5 guest B avatar");
            Check(b.state.stations[4].selection==state.selection&&Math.Abs(b.state.stations[4].timerDeadline-deadline)<.000001,"Late join restores the actual selected method and exact deadline");yield return Send(a,4,ArchiveAction.Submit,spoof:true);Check(session.State.mistakes.Count==1&&session.State.mistakes[0].actor==a.Actor&&state.round==0&&state.lastAnswerActor==a.Actor,"Wrong method charges the authenticated sender despite a forged actor field");
            revision=session.State.revision;Packet(a,lastCommand);yield return .25f;Check(session.State.revision==revision&&session.State.mistakes.Count==1,"Replayed method submission cannot add another mistake");var fake=JsonUtility.FromJson<ArchiveTeamState>(JsonUtility.ToJson(session.State));fake.revision+=1000;fake.stations[4].phase=2;b.client.OpRaiseEvent(ArchiveTopicSession.SnapshotEvent,new object[]{ArchiveTopicSession.Channel,JsonUtility.ToJson(fake)},new RaiseEventOptions{Receivers=ReceiverGroup.All},SendOptions.SendReliable);yield return .25f;Check(session.ActiveTopic==4&&a.state.stations[4].phase==1,"Guest snapshot cannot forge Proof Forge completion");
            int method=state.selection;state.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return Wait(()=>state.timerExpired&&b.state.stations[4].timerExpired,"T5 method timeout replicates",8);Check(state.selection==method&&b.state.stations[4].selection==method&&session.State.mistakes.Count==2&&session.State.mistakes.Last().actor==a.Actor,"Identification timeout retains selected method and charges the Book activator once");yield return BlockedBook(b,1,"Timed-out T5 still reserves the unfinished team topic");
            yield return Move(b,st,ArchiveTopicStation.BookPosition+Vector3.back*1.7f);yield return Send(b,4,ArchiveAction.Start);Check(state.selection==method&&state.timerAttempt==2&&state.timerActor==b.Actor,"Teammate retries the same method answer at the Book");deadline=state.timerDeadline;yield return MethodChoice(b,q.method);yield return Send(b,4,ArchiveAction.Submit);Check(state.round==1&&state.reveal.Contains(q.trial.explanation)&&Math.Abs(state.timerDeadline-deadline)<.000001,"Teammate corrects the same method and shares its original explanation");
            yield return BlockedBook(b,2,"T5 remains reserved between challenges");yield return Move(b,st,ArchiveTopicStation.BookPosition+Vector3.back*1.7f);yield return Send(b,4,ArchiveAction.Start);q=session.Question(4);Check(q.trial.kind==TrialProofKind.ArrangeSteps&&state.selection==-1&&state.placements.Length==5,"Assigned proof starts five tablets without a redundant method selection");
            yield return Move(a,st,st.CurrentItemPosition(0,q,state));yield return Send(a,4,ArchiveAction.Pick,0);yield return Move(b,st,st.CurrentItemPosition(0,q,state));revision=session.State.revision;Packet(b,Command(b,4,ArchiveAction.Pick,0));yield return .25f;Check(session.State.revision==revision&&state.carries.Count==1&&state.carries[0].actor==a.Actor,"Guest cannot steal a teammate's carried tablet");
            PhotonNetwork.SetMasterClient(PhotonNetwork.CurrentRoom.GetPlayer(a.Actor));yield return Wait(()=>!PhotonNetwork.IsMasterClient&&a.client.CurrentRoom.MasterClientId==a.Actor,"T5 live master handoff");a.client.CurrentRoom.SetMasterClient(a.client.CurrentRoom.GetPlayer(PhotonNetwork.LocalPlayer.ActorNumber));yield return Wait(()=>PhotonNetwork.IsMasterClient,"T5 Editor regains authority");yield return .2f;state=session.State.stations[4];Check(state.round==1&&state.carries.Count==1&&state.carries[0].actor==a.Actor&&Math.Abs(state.timerDeadline-deadline)<.000001,"Master handoff keeps solved identification, carried tablet and deadline");
            int former=a.Actor;a.client.Disconnect();yield return Wait(()=>PhotonNetwork.CurrentRoom.GetPlayer(former)==null,"T5 starter leaves");yield return .2f;Check(state.carries.Count==0&&session.ActiveTopic==4&&session.ActorName(former)=="Archive guest A QA"&&session.State.mistakes[0].actor==former,"Departure returns held tablets while preserving reservation and mistake identity");
            var answer=ArchiveTopicChecks.Solution(q).placements;yield return TabletPlace(b,answer[0],0);var partial=state.placements.ToArray();int before=session.State.mistakes.Count;state.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return Wait(()=>state.timerExpired&&b.state.stations[4].timerExpired,"T5 tablet timeout replicates",8);Check(state.round==1&&state.placements.SequenceEqual(partial)&&session.State.mistakes.Count==before+1&&session.State.mistakes.Last().actor==b.Actor,"Timeout retains the unfinished proof and charges the current Book activator once");yield return Move(b,st,ArchiveTopicStation.BookPosition+Vector3.back*1.7f);yield return Send(b,4,ArchiveAction.Start);Check(state.placements.SequenceEqual(partial)&&state.timerAttempt==3,"Guest Book retry keeps current tablet arrangement");
            Status="T5 capture restrictions";yield return Move(b,st,st.CurrentItemPosition(answer[1],q,state));var capture=session.hunting.GetSnapshot();capture.state=(int)KhezuHuntState.Caught;capture.target=capture.caught=b.Actor;capture.captureSerial++;capture.huntSerial++;capture.capturePosition=session.ActorPlayer(b.Actor).transform.position;capture.captureAnchorValid=true;capture.captureStartedAt=KhezuHuntingController.EncounterClock-3;capture.encounterPhase=4;capture.awake=true;capture.pending=false;capture.animation="Idle";capture.animationSpeed=1;session.hunting.ApplySnapshot(capture,true);yield return .25f;Check(!session.CanAct(b.Actor)&&session.CanAct(PhotonNetwork.LocalPlayer.ActorNumber),"Only the captured player loses topic interaction authority");revision=session.State.revision;Packet(b,Command(b,4,ArchiveAction.Pick,answer[1]));yield return .25f;Check(session.State.revision==revision&&state.carries.Count==0,"Captured guest cannot pick a valid nearby tablet");session.hunting.Request(KhezuCommand.Sleep);yield return .2f;
            Status="Five T5 challenges over Photon";for(int r=state.round;r<5;r++){
                if(state.phase==0){yield return Move(b,st,ArchiveTopicStation.BookPosition+Vector3.back*1.7f);yield return Send(b,4,ArchiveAction.Start);if(r==2)Check(state.placements.Length==5&&state.placements.All(p=>p==-1),"Network Book-gate timeout starts the next proof with empty sockets");}q=session.Question(4);answer=ArchiveTopicChecks.Solution(q).placements;yield return TabletArrange(b,answer);if(ArchiveMethodPresentation.NeedsMethod(q))yield return MethodChoice(b,q.method);yield return Send(b,4,ArchiveAction.Submit);Check(state.round==r+1&&b.state.stations[4].round==r+1&&state.reveal.Contains(q.trial.explanation),"Photon stage "+(r+1)+" shares accepted method, proof and explanation");
                if(r==1){state.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return Wait(()=>state.timerExpired&&b.state.stations[4].timerExpired,"T5 Book gate timeout replicates",8);Check(state.round==2&&state.placements.Length==0&&b.state.stations[4].placements.Length==0,"Gate timeout cannot clone solved tablet IDs into the next networked challenge");}
            }
            Check(state.phase==2&&!state.timerRunning&&session.ActiveTopic==-1,"Five shared Proof Forge stages freeze time and release the next topic");Check(session.State.stations.Where(s=>s.topic!=4).All(s=>s.round==0&&s.timerAttempt==0),"T5 network play preserves every other topic's state and clock");Status="Completed T5 transport checks";
        }
    }
}
